namespace Kirie.Api.Cities;

/// <summary>
/// A page of the book. Terrain and skyline say what the paper landscape is cut
/// from, back to front; the shapes themselves are generated by the client.
/// </summary>
public sealed record City(
    string Id,
    string Name,
    string Country,
    double Latitude,
    double Longitude,
    string TimeZone,
    string[] Terrain,
    string Skyline)
{
    public TimeZoneInfo Zone { get; } = TimeZoneInfo.FindSystemTimeZoneById(TimeZone);
}

public static class Terrain
{
    public const string Sea = "sea";
    public const string Mountains = "mountains";
    public const string Hills = "hills";
    public const string Plains = "plains";
    public const string Desert = "desert";
    public const string Ice = "ice";
    public const string Forest = "forest";
    public const string River = "river";
    public const string Volcano = "volcano";
}

public static class Skyline
{
    public const string Towers = "towers";
    public const string City = "city";
    public const string Town = "town";
    public const string None = "none";
}

